def is_touching(a: ImagePatch, b: ImagePatch, margin: float = 0.0) -> bool:
    return abs(distance(a, b)) <= margin

def is_wearing(item: ImagePatch, person: ImagePatch, margin: float = 0.0) -> bool:
    return is_touching(item, person, margin)

