def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    umbrella_patches = image_patch.find("umbrella")
    if not umbrella_patches: 
        return image_patch

    red_white_umbrellas = [u for u in umbrella_patches if u.best_text_match(["red and white"])]

    if len(red_white_umbrellas) == 0:
        return image_patch

    white_umbrellas = [u for u in umbrella_patches if u.best_text_match(["white"])]

    if len(white_umbrellas) == 0:
        return image_patch

    closest_red_white = min(red_white_umbrellas, key=lambda u: u.compute_depth())
    closest_white = min(white_umbrellas, key=lambda u: u.compute_depth())

    if abs(closest_red_white.horizontal_center - closest_white.horizontal_center) < abs(closest_red_white.vertical_center - closest_white.vertical_center):
        return closest_white
    else:
        return closest_red_white

modern_c4_ds.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    umbrella_patches = image_patch.find("umbrella")
    white_umbrellas = [u for u in umbrella_patches if u.verify_property("umbrella", "white")]

    if not white_umbrellas:
        return image_patch

    white_umbrellas.sort(key=lambda u: u.horizontal_center)
    next_to_white = []

    for i, white in enumerate(white_umbrellas):
        if i > 0 and i < len(white_umbrellas) - 1:
            prev_white = white_umbrellas[i - 1]
            next_white = white_umbrellas[i + 1]
            if distance(prev_white, white) < 100 and distance(next_white, white) < 100:
                next_to_white.append(white)

    if next_to_white:
        return next_to_white[0]
    else:
        return white_umbrellas[0]

